import functools


def log(func):
    """Announce each call, then get out of the way."""
    calls = []

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        calls.append(func.__name__)
        func(*args, **kwargs)

    wrapper.calls = calls
    return wrapper


@log
def double(n):
    return n * 2

def timed(func):
    """Count how long each call takes."""

    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)

    return wrapper


@timed
def fetch(url):
    """Fetch a URL and return its body."""
    return f"body of {url}"

import functools


def retry(times):
    """Call the function again, up to `times` attempts, until it works."""

    @functools.wraps(times)
    def wrapper(*args, **kwargs):
        for attempt in range(times):
            try:
                return times(*args, **kwargs)
            except ValueError:
                if attempt == times - 1:
                    raise
        return None

    return wrapper


@retry(times=3)
def flaky(box):
    box.append(1)
    if len(box) < 3:
        raise ValueError("not yet")
    return "ok"

import functools


def audit(label="call"):
    """Record every call under a label."""
    record = []

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            record.append(label)
            return func(*args, **kwargs)

        wrapper.record = record
        return wrapper

    return decorator


@audit
def charge(pence):
    return pence * 2


print(charge(5))

import functools


def cached(func):
    store = {}

    @functools.wraps(func)
    def wrapper(user, key):
        if key not in store:
            store[key] = func(user, key)
        return store[key]

    return wrapper


def authorised(func):
    @functools.wraps(func)
    def wrapper(user, key):
        if user != "admin":
            raise PermissionError("not allowed")
        return func(user, key)

    return wrapper


@cached
@authorised
def read(user, key):
    return f"value of {key}"

tests:
assert read("admin", "a") == "value of a"

try:
    read("guest", "a")
except PermissionError:
    pass
else:
    raise AssertionError("a guest was served from the cache")

